entries[457818] = { ["name"] = "Dunkle Dämpfung", ["text"] = "100 Meter Reichweite\nSofort\nEin Verehrer der Gesichtslosen erscheint durch ein aufbrechendes Portal, verursacht dabei 1394132 Schattenschaden und bringt getroffene Gegner für 4 Sek. zum Schweigen.\n\nDer Verehrer kanalisiert dunkle Macht in einer Linie auf Nerl'athekk und erhöht so dessen Angriffstempo um 50%, bis die Kanalisierung gestört wird." }
