entries[457838] = { ["name"] = "Goblinhand aufstellen", ["text"] = "50 Meter Reichweite\nSofort\nGoblins haben gesehen, wozu die Vindikaar imstande ist, und wollten diese Macht selbst in Händen halten. Nun ist sie in Euren Händen.\n\nIn die Nähe von ausschwärmenden Skardyn werfen.\n\nHält 15 Sek. lang an." }
