entries[458458] = { ["name"] = "Karnivorenkraftprobe", ["text"] = "Sofort\nUlgrax speit Spinnweben auf einen Spielercharakter und alle Verbündeten im Umkreis von 10 Metern und verursacht 17331401 Naturschaden, die gleichmäßig auf alle Spielercharaktere aufgeteilt werden, und fesselt sie an Ulgrax.\n\nGefesselte Spielercharaktere erleiden alle 2 Sek. 575632 Naturschaden und werden zu Ulgrax gezogen. Die Stärke, mit der Ulgrax die Spielercharaktere anzieht, wird für jeden gefesselten Spielercharakter verringert." }
entries[458459] = { ["name"] = "Spalten", ["text"] = "Nahkampfreichweite\nSofort\nGreift alle Gegner vor Euch an, fügt ihnen (217.745% der Angriffskraft) körperlichen Schaden zu und belegt sie mit 'Tiefe Wunden'. 'Spalten' verbraucht Euren Effekt 'Überwältigen', um mehr Schaden zu verursachen. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu." }
entries[458460] = { ["name"] = "Götze der brutalen Kraft", ["text"] = "100 Meter Reichweite\nSofort\nSpringt auf Brann, wenn er dazu auffordert, damit er Spielercharaktere auf ihre Gegner schleudert, was diese zurückstößt und ihnen erheblichen körperlichen Schaden zufügt, der unter ihnen aufgeteilt wird. Dieser Effekt hat eine Chance, bis zu 2 -mal hintereinander aufzutreten." }
