entries[458752] = { ["name"] = "Gemetzel", ["text"] = "Ca. 1.1 Procs pro Minute\n'Bluttrinker' und 'Verzehr' wirken sich jetzt auf Eure Meisterschaft: Blutschild aus.\n\nJedes Mal, wenn ein Gegner Euren Blutschild trifft, besteht die Chance, dass die Abklingzeiten von 'Bluttrinker' und 'Verzehr' zurückgesetzt werden." }
entries[458753] = { ["name"] = "Blutige Klinge", ["text"] = "Das Parieren eines Angriffs gewährt Euch eine Aufladung von 'Blutige Klinge', wodurch Eure Stärke 15 Sek. lang um 0.5% erhöht wird, bis zu einem Maximum von 4.0%.\n\nBei 8 Stapeln verbraucht Euer nächstes Parieren alle Aufladungen, um einen 'Herzstoß' mit einer Effektivität von 300% zu entfesseln und Eure Stärke 6 Sek. lang um 10% zu erhöhen.\n(500ms Abklingzeit)" }
entries[458762] = { ["name"] = "Verheeren", ["text"] = "Sofort\nDer Zaubernde verheert 6 Sek. lang Spielercharaktere vor sich, verursacht so alle 1.5 Sek. körperlichen Schaden und fügt getroffenen Spielercharakteren 10 Sek. lang alle 2 Sek. zusätzlichen körperlichen Schaden zu. Dieser Effekt ist stapelbar." }
entries[458763] = { ["name"] = "Fesselndes Lied", ["text"] = "50 Meter Reichweite\nWirken in 3 sek.\nFesselt den anvisierten Spielercharakter mit einem Lied." }
