entries[458767] = { ["name"] = "Verheeren", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nDer Zaubernde verheert 6 Sek. lang Spielercharaktere vor sich, verursacht so alle 1.5 Sek. körperlichen Schaden und fügt getroffenen Spielercharakteren 10 Sek. lang alle 2 Sek. zusätzlichen körperlichen Schaden zu. Dieser Effekt ist stapelbar." }
entries[458770] = { ["name"] = "Schwefelbolzen", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde schleudert einen Schwefelbolzen auf das Ziel. Verursacht Feuerschaden und verbrennt das Ziel, um ihm 8 Sek. lang alle 2 Sek. zusätzlichen Feuerschaden zuzufügen." }
